import { useEffect, useState } from 'react';
import { useApp } from './context/AppContext';
import PostCard from './PostCard';

const CHATROOMS = [
  { id: 'Coding', icon: '💻', title: 'Coding', subtitle: 'Talk code with devs' },
  { id: 'Gaming', icon: '🎮', title: 'Gaming', subtitle: 'Squad up and play' },
  { id: 'Drawing', icon: '🎨', title: 'Drawing', subtitle: 'Share your art' },
];

export default function FeedPage() {
  const { posts, postsLoaded, setPosts, setPostsLoaded, hobbies } = useApp();
  const [status, setStatus] = useState(postsLoaded ? 'ready' : 'loading');

  useEffect(() => {
    if (postsLoaded) {
      setStatus('ready');
      return undefined;
    }

    let cancelled = false;
    setStatus('loading');

    fetch('/posts.json')
      .then((res) => {
        if (!res.ok) throw new Error('Failed to load posts');
        return res.json();
      })
      .then((data) => {
        if (cancelled) return;
        setPosts(data);
        setPostsLoaded(true);
        setStatus('ready');
      })
      .catch(() => {
        if (!cancelled) setStatus('error');
      });

    return () => {
      cancelled = true;
    };
  }, [postsLoaded, setPosts, setPostsLoaded]);

  const visiblePosts =
    hobbies.length === 0 ? posts : posts.filter((p) => hobbies.includes(p.hobby));

  return (
    <div className="feed-layout">
      <main className="feed-main">
        {status === 'loading' && <p className="status-msg">Loading posts…</p>}
        {status === 'error' && (
          <p className="status-msg error">Something went wrong loading posts.</p>
        )}
        {status === 'ready' && visiblePosts.length === 0 && (
          <p className="status-msg">No posts found for your selected hobbies.</p>
        )}
        {status === 'ready' &&
          visiblePosts.map((post) => <PostCard key={post.id} post={post} />)}
      </main>
      <aside className="feed-sidebar">
        <div className="chatroom-card">
          <h2>Chatrooms</h2>
          <ul className="chatroom-list">
            {CHATROOMS.map((room) => (
              <li key={room.id} className="chatroom-item">
                <span className="chatroom-icon">{room.icon}</span>
                <div className="chatroom-text">
                  <span className="chatroom-title">{room.title}</span>
                  <span className="chatroom-subtitle">{room.subtitle}</span>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </aside>
    </div>
  );
}
